with reviewed as (
  select * from jsonb_to_recordset($photos$[{"name_en":"Kenya Thunguri AA – Filter","source_url":"https://www.fiveelephant.com/products/kenya-thunguri-aa-filter","image_url":"https://cdn.shopify.com/s/files/1/0181/5693/files/Thunguri.jpg?v=1781512841"},{"name_en":"Rwanda Mbilima Soil Project Lot.0704","source_url":"https://kurasu.kyoto/products/rwanda-mbilima-soil-project-lot-0704light-roast","image_url":"https://cdn.shopify.com/s/files/1/0801/9439/files/image_Beans_Single_Rwanda-Mbilima-Soil-Project-Lot.0704-2026.jpg?v=1779845863"},{"name_en":"Indonesia Frinsa Estate Weninggalih","source_url":"https://kurasu.kyoto/products/indonesia-frinsa-estate-weninggalih-light-roast","image_url":"https://cdn.shopify.com/s/files/1/0801/9439/files/image_Beans_Single_Indonesia-Frinsa-Estate-Weninggalih-2026.jpg?v=1789108519"},{"name_en":"Gachatha","source_url":"https://timwendelboe.no/products/gachatha","image_url":"https://cdn.shopify.com/s/files/1/0738/6113/6597/files/GachathaFilter-WEBSHOP_6f45620d-c6e7-4250-b377-4f0c98c5afd5.webp?v=1780987387"},{"name_en":"Finca Tamana Caturron","source_url":"https://timwendelboe.no/products/finca-tamana-caturron","image_url":"https://cdn.shopify.com/s/files/1/0738/6113/6597/files/FincaTamanaCaturronFilter-WEBSHOP.webp?v=1783670937"},{"name_en":"Alba — 250 g","source_url":"https://rawicoffee.com/shop/القهوة/حبوب-القهوة/ألبا-250-جرام/","image_url":"https://rawicoffee.com/wp-content/uploads/2026/04/173572-scaled.jpg"},{"name_en":"Romario — Brazil","source_url":"https://jeblacoffeeroasters.com/ar/products/روماريو-برازيل","image_url":"https://cdn.shopify.com/s/files/1/0883/8309/5058/files/D7DDBE24-0E48-4643-838D-ED39A0023719.jpg?v=1780519091"},{"name_en":"Colombia El Mesón – Filter","source_url":"https://www.fiveelephant.com/products/colombia-el-meson-filter","image_url":"https://cdn.shopify.com/s/files/1/0181/5693/files/Elmeson.jpg?v=1788770146"},{"name_en":"Ethiopia Kello Lalesa – Filter","source_url":"https://www.fiveelephant.com/products/ethiopia-kelloo-lalesa","image_url":"https://cdn.shopify.com/s/files/1/0181/5693/files/Lalesa.jpg?v=1784199351"},{"name_en":"Kenya Gatomboya AB","source_url":"https://kurasu.kyoto/products/kenya-gatomboya-ab-light-roast","image_url":"https://cdn.shopify.com/s/files/1/0801/9439/files/image_Beans_Single_Kenya-Gatomboya-AB-2026.jpg?v=1779850609"},{"name_en":"Colombia Hermides Meneses","source_url":"https://kurasu.kyoto/products/colombia-hermides-meneses-light-roast","image_url":"https://cdn.shopify.com/s/files/1/0801/9439/files/image_Beans_Single_Colombia-Hermides-Meneses-2026.jpg?v=1787109166"},{"name_en":"El Salvador Don Jaime","source_url":"https://kurasu.kyoto/products/el-salvador-don-jaimemedium-light-roast","image_url":"https://cdn.shopify.com/s/files/1/0801/9439/files/image_Beans_El-Salvador-Don-Jaime-2026.jpg?v=1788311387"},{"name_en":"El Salvador Emerson Vasquez Pacamara","source_url":"https://kurasu.kyoto/products/el-salvador-emerson-vasquez-pacamara-light-roast","image_url":"https://cdn.shopify.com/s/files/1/0801/9439/files/image_Beans_Single_El-Salvador-Emerson-VasquezPacamara-2026.jpg?v=1776071969"},{"name_en":"Los Pirineos Pacamara","source_url":"https://timwendelboe.no/products/los-pirineos-pacamara","image_url":"https://cdn.shopify.com/s/files/1/0738/6113/6597/files/LosPirineosPacamaraFilter-WEBSHOP_4585f953-a12d-4790-8286-ae71d423e898.webp?v=1785757614"},{"name_en":"Shantawene","source_url":"https://lacabra.com/products/shantawene","image_url":"https://cdn.shopify.com/s/files/1/1094/5212/files/Shantawene_La_Cabra_Seasonal_Coffee_box_250g_e778abc0-82fa-4e9e-9c55-b95d085cca77.webp?v=1789565421"},{"name_en":"Kii","source_url":"https://lacabra.com/products/kii","image_url":"https://cdn.shopify.com/s/files/1/1094/5212/files/Kii_La_Cabra_Seasonal_Coffee_Box_250g.webp?v=1783488439"},{"name_en":"Julian Calderón Pink Bourbon","source_url":"https://lacabra.com/products/julian-calderon-pink-bourbon","image_url":"https://cdn.shopify.com/s/files/1/1094/5212/files/Julian_Calder_n_Pink_Bourbon_La_Cabra_Highlight_Coffee_Box_200g.webp?v=1790061203"}]$photos$::jsonb) as x(name_en text,source_url text,image_url text)
)
update public.beans b set image_url=x.image_url,image_source_url=x.source_url,image_usage_status='source_linked',image_kind='packaging'
from reviewed x where b.name_en=x.name_en and b.source_url=x.source_url
and b.is_published and not b.requires_review and b.image_url is null
and coalesce(b.image_usage_status,'rights_unknown') not in ('removal_requested','rights_confirmed');
